import logging
from ta_moler.device.nokia_proxy_pc3 import NokiaProxyPc3
from moler.helpers import call_base_class_method_with_same_name, mark_to_call_base_class_method_with_same_name


@call_base_class_method_with_same_name
class Egate3(NokiaProxyPc3):
    r"""
    Egate device class.

    Example of device in yaml configuration file:
    - with PROXY_PC:
      EGATE_PROXY_PC:
        DEVICE_CLASS: ta_moler.device.egate.Egate
        INITIAL_STATE: UNIX_LOCAL
        CONNECTION_HOPS:
          UNIX_LOCAL:
            PROXY_PC:
              execute_command: ssh
              command_params:
                expected_prompt: "proxy_pc#"
                host: proxy_pc_host
                login: proxy_pc_login
                password: password
                set_timeout: null
          EGATE:
            PROXY_PC:
              execute_command: exit
              command_params:
                expected_prompt: "proxy_pc#"
          EGATE_UNIX:
            PROXY_PC:
              execute_command: exit
              command_params:
                expected_prompt: "proxy_pc#"

          PROXY_PC:
            EGATE:
              execute_command: telnet
              command_params:
                expected_prompt: "EGATE>"
            EGATE_UNIX:
              execute_command: ssh
              command_params:
                host: egate_ip
            UNIX_LOCAL:
              execute_command: exit
              command_params:
                expected_prompt: "moler_bash#"
    - without PROXY_PC:
      EGATE:
        DEVICE_CLASS: ta_moler.device.egate.Egate
        INITIAL_STATE: UNIX_LOCAL
        CONNECTION_HOPS:
          UNIX_LOCAL:
            EGATE:
              execute_command: telnet
              command_params:
                expected_prompt: "EGATE>"
                host: epc_host
            EGATE_UNIX:
              execute_command: ssh
              command_params:
                host: epc_host
          EGATE:
            UNIX_LOCAL:
              execute_command: exit
              command_params:
                expected_prompt: "moler_bash#"
    """

    egate = "EGATE"
    egate_unix = "EGATE_UNIX"
    _re_egate_unix_prompt = r"\w+@[\w\d-]+:.*$"

    def __init__(self, sm_params, name=None, io_connection=None, io_type=None, variant=None, io_constructor_kwargs=None,
                 initial_state=None, lazy_cmds_events=False):
        """
        Create unix device communicating over io_connection.

        :param io_connection: External-IO connection having embedded moler-connection
        :param io_type: External-IO connection connection type
        :param variant: External-IO connection variant
        :param io_constructor_kwargs: additional parameter into constructor of selected connection type
                        (if not given then default one is taken)
        :param initial_state: Initial state for device
        :param lazy_cmds_events: set False to load all commands and events when device is initialized, set True to load
                        commands and events when they are required for the first time.
        """
        sm_params = sm_params.copy()
        initial_state = initial_state if initial_state is not None else self.egate
        super(Egate3, self).__init__(sm_params=sm_params, name=name, io_connection=io_connection, io_type=io_type,
                                     variant=variant, io_constructor_kwargs=io_constructor_kwargs,
                                     initial_state=initial_state, lazy_cmds_events=lazy_cmds_events)
        self.logger = logging.getLogger('moler.epcsim')

    @mark_to_call_base_class_method_with_same_name
    def _get_default_sm_configuration_with_proxy_pc(self):
        """
        Return State Machine default configuration with proxy_pc state.

        :return: default sm configuration with proxy_pc state.
        """
        config = {
            self.connection_hops: {
                self.proxy_pc: {  # from
                    self.egate: {  # to
                        "execute_command": "telnet",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": r'EGATE>',
                            "host": "0",
                            "port": 60001,
                            "set_timeout": '~ statusbar=off',
                            "target_newline": "\n"

                        },
                        "required_command_params": [
                        ]
                    },
                    self.egate_unix: {  # to
                        "execute_command": "ssh",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": Egate3._re_egate_unix_prompt,
                            "login": "ute",
                            "password": "ute",
                            "host": "0",
                            "known_hosts_on_failure": "rm",
                            "target_newline": "\n",
                        },
                        "required_command_params": [
                        ]
                    }
                },
                self.egate: {  # from
                    self.proxy_pc: {  # to
                        "execute_command": "exit_telnet",  # using command
                        "command_params": {  # with parameters
                            "target_newline": "\n",
                        },
                        "required_command_params": [
                            "expected_prompt"
                        ]
                    }
                },
                self.egate_unix: {  # from
                    self.proxy_pc: {  # to
                        "execute_command": "exit",  # using command
                        "command_params": {  # with parameters
                        },
                        "required_command_params": [
                            "expected_prompt"
                        ]
                    }
                }
            }
        }
        return config

    @mark_to_call_base_class_method_with_same_name
    def _get_default_sm_configuration_without_proxy_pc(self):
        """
        Return State Machine default configuration without proxy_pc state.

        :return: default sm configuration without proxy_pc state.
        """
        config = {
            self.connection_hops: {
                self.unix_local: {  # from
                    self.egate: {  # to
                        "execute_command": "telnet",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": r'EGATE>',
                            "port": 60001,
                            "set_timeout": '~ statusbar=off',
                            'target_newline': '\n',
                        },
                        "required_command_params": [
                            "host",
                        ]
                    },
                    self.egate_unix: {  # to
                        "execute_command": "ssh",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": Egate3._re_egate_unix_prompt,
                            "login": "ute",
                            "password": "ute",
                            "known_hosts_on_failure": "rm",
                            'target_newline': '\n',
                        },
                        "required_command_params": [
                            "host",
                        ]
                    }
                },
                self.egate: {  # from
                    self.unix_local: {  # to
                        "execute_command": "exit_telnet",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": r'^moler_bash#',
                            'target_newline': '\n',
                        },
                        "required_command_params": [
                        ]
                    }
                },
                self.egate_unix: {  # from
                    self.unix_local: {  # to
                        "execute_command": "exit",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": r'^moler_bash#',
                            'target_newline': '\n',
                        },
                        'required_command_params': [
                        ]
                    }
                }
            }
        }
        return config

    @mark_to_call_base_class_method_with_same_name
    def _prepare_transitions_with_proxy_pc(self):
        """
        Prepare transitions to change states with proxy_pc state.

        :return: transitions with proxy_pc state.
        """
        transitions = {
            self.egate: {
                self.proxy_pc: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
            self.proxy_pc: {
                self.egate: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                },
                self.egate_unix: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
            self.egate_unix: {
                self.proxy_pc: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },

        }
        return transitions

    @mark_to_call_base_class_method_with_same_name
    def _prepare_transitions_without_proxy_pc(self):
        """
        Prepare transitions to change states without proxy_pc state.

        :return: transitions without proxy_pc state.
        """
        transitions = {
            self.egate: {
                self.unix_local: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
            self.unix_local: {
                self.egate: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                },
                self.egate_unix: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
            self.egate_unix: {
                self.unix_local: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
        }
        return transitions

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_with_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine with proxy_pc state.

        :return: textual prompt for each state with proxy_pc state.
        """
        state_prompts = {
            self.egate:
                self._configurations[self.connection_hops][self.proxy_pc][self.egate][
                    "command_params"]["expected_prompt"],
            self.egate_unix:
                self._configurations[self.connection_hops][self.proxy_pc][self.egate_unix][
                    "command_params"]["expected_prompt"],
        }
        return state_prompts

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_without_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine without proxy_pc state.

        :return: textual prompt for each state without proxy_pc state.
        """
        state_prompts = {
            self.egate:
                self._configurations[self.connection_hops][self.unix_local][self.egate][
                    "command_params"]["expected_prompt"],
            self.egate_unix:
                self._configurations[self.connection_hops][self.unix_local][self.egate_unix][
                    "command_params"]["expected_prompt"],
            self.unix_local:
                self._configurations[self.connection_hops][self.egate][self.unix_local][
                    "command_params"]["expected_prompt"],
        }
        return state_prompts

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_hops_with_proxy_pc(self):
        """
        Prepare non direct transitions for each state for State Machine with proxy_pc state.

        :return: non direct transitions for each state with proxy_pc state.
        """
        state_hops = {
            self.not_connected: {
                self.egate: self.unix_local,
                self.egate_unix: self.unix_local,
            },
            self.unix_local: {
                self.egate: self.proxy_pc,
                self.egate_unix: self.proxy_pc,
            },
            self.egate: {
                self.not_connected: self.proxy_pc,
                self.unix_local: self.proxy_pc,
                self.unix_local_root: self.proxy_pc,
                self.egate_unix: self.proxy_pc,
            },
            self.unix_local_root: {
                self.egate: self.unix_local,
                self.egate_unix: self.unix_local,
            },
            self.egate_unix: {
                self.not_connected: self.proxy_pc,
                self.unix_local: self.proxy_pc,
                self.unix_local_root: self.proxy_pc,
                self.egate: self.proxy_pc,
            }
        }
        return state_hops

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_hops_without_proxy_pc(self):
        state_hops = {
            self.not_connected: {
                self.egate: self.unix_local,
                self.egate_unix: self.unix_local,
            },
            self.egate: {
                self.not_connected: self.unix_local,
                self.unix_local_root: self.unix_local,
                self.egate_unix: self.unix_local,
            },
            self.unix_local_root: {
                self.egate: self.unix_local,
                self.egate_unix: self.unix_local,
                self.not_connected: self.unix_local,
            },
            self.egate_unix: {
                self.egate: self.unix_local,
                self.not_connected: self.unix_local,
                self.unix_local_root: self.unix_local,
            }
        }
        return state_hops

    def _get_packages_for_state(self, state, observer):
        """
        Get available packages contain cmds and events for each state.

        :param state: device state.
        :param observer: observer type, available: cmd, events
        :return: available cmds or events for specific device state.
        """
        available = super(Egate3, self)._get_packages_for_state(state, observer)

        if not available:
            if state == self.egate:
                available = {self.cmds: ['ta_moler.cmd.egate'],
                             self.events: ['moler.events.shared', 'ta_moler.events.egate']}
            elif state == self.egate_unix:
                available = {self.cmds: ['moler.cmd.unix', 'ta_moler.cmd.shared.nokiaunix'],
                             self.events: ['moler.events.shared', 'moler.events.unix']}
            if available:
                return available[observer]

        return available
